import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';

interface ITransactionTypeProps extends HTMLAttributes<HTMLDivElement> {
	amount: string;
}

export const TransactionType: FC<ITransactionTypeProps> = ({ amount, ...props }) => {
	const { t } = useTranslation();
	const amountValue = !isNaN(Number(amount)) ? Number(amount) : 0;

	return <Typography.Text {...props}>{amountValue > 0 ? t('Пополнение') : t('Списание')}</Typography.Text>;
};
