import { FC, HTMLAttributes } from 'react';

import { Typography } from 'antd';

import { ETransactionReasons } from 'entities/Transaction/model/types';
import { useTrans } from 'shared/hooks';

interface ITransactionReasonProps extends HTMLAttributes<HTMLDivElement> {
	reason: ETransactionReasons;
}

export const TransactionReason: FC<ITransactionReasonProps> = ({ reason, ...props }) => {
	const { transactionReasons } = useTrans();

	return <Typography.Text {...props}>{transactionReasons[reason] || reason}</Typography.Text>;
};
