import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button } from 'antd';

import ArrowIcon from 'assets/images/icons/arrow-right.svg?react';
import WalletIcon from 'assets/images/menu/finances.svg?react';
import ReportsIcon from 'assets/images/menu/reports.svg?react';
import { EReportTypes } from 'entities/Report';
import { ETransactionReasons, ITransaction } from 'entities/Transaction';
import { EFilters } from 'features/Filters';
import { useMedia } from 'shared/hooks';
import { EMainRoutes, EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

interface ITransactionButtonsProps extends HTMLAttributes<HTMLDivElement> {
	transaction: ITransaction;
}

export const TransactionButtons: FC<ITransactionButtonsProps> = ({ transaction }) => {
	const { t } = useTranslation();
	const isLg = useMedia('lg');
	const amountValue = !isNaN(Number(transaction.amount)) ? Number(transaction.amount) : 0;

	if (amountValue > 0 || transaction.reason === ETransactionReasons.ADJUSTMENT) {
		return (
			<ButtonStyleLink
				variant="text"
				color={isLg ? 'default' : 'primary'}
				icon={isLg ? <ReportsIcon /> : <ArrowIcon />}
				iconPosition="end"
				size="small"
				to={`/${EMainRoutes.REPORTS}?${EFilters.REPORT_TYPE}=${EReportTypes.ACTION}&${EFilters.SEARCH_ID}=${transaction.action_uuid}`}
				onClick={() => {
					sendYmEvent({
						event: EYmEvents.CLICK_GO_TO_STATISTIC,
						o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.FINANCE],
						o2: [EYmEventsO2.FINANCE, EYmEventsO2.BALANCE_HISTORY],
						isMarketing: false,
					});
				}}>
				{isLg ? '' : t('Перейти в статистику')}
			</ButtonStyleLink>
		);
	} else {
		return (
			<Button
				variant="text"
				color={isLg ? 'default' : 'primary'}
				icon={isLg ? <WalletIcon /> : <ArrowIcon />}
				iconPosition="end"
				size="small"
				href={import.meta.env.VITE_WALLET_URL}
				target="_blank"
				onClick={() => {
					sendYmEvent({
						event: EYmEvents.CLICK_GO_TO_WALLET,
						o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.FINANCE],
						o2: [EYmEventsO2.FINANCE, EYmEventsO2.BALANCE_HISTORY],
						isMarketing: false,
					});
				}}>
				{isLg ? '' : t('Перейти в Wallet')}
			</Button>
		);
	}
};
