import { HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { DatePicker, Select } from 'antd';
import cn from 'classnames';

import { useDateFilters } from 'features/Filters';
import { useFilters } from 'features/Filters/hooks/useFilters';
import { EFilters } from 'features/Filters/types/enums';
import { useTrans } from 'shared/hooks';

import styles from './TransactionsFilters.module.scss';

export interface ITransactionsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const TransactionsFilters = ({ className, ...props }: ITransactionsFiltersProps) => {
	const { t } = useTranslation();
	const { transactionTypes } = useTrans();
	const { onFilterChange, getALLFilterValues } = useFilters();
	const { dateAfter, dateBefore, onDateChange } = useDateFilters(EFilters.CREATED_AT_AFTER, EFilters.CREATED_AT_BEFORE);

	return (
		<div {...props} className={cn(className, styles.filters)}>
			{/*<DatePicker.RangePicker
				size="small"
				format="DD.MM.YYYY"
				placeholder={[t('Дата с'), t('Дата по')]}
				value={[dateAfter, dateBefore]}
				onChange={(value) => {
					onDateChange(value?.[0] || null, EFilters.CREATED_AT_AFTER);
					onDateChange(value?.[1] || null, EFilters.CREATED_AT_BEFORE);
				}}
			/>*/}

			<DatePicker
				size="small"
				format="DD.MM.YYYY"
				placeholder={t('Дата с')}
				value={dateAfter}
				onChange={(value) => onDateChange(value, EFilters.CREATED_AT_AFTER)}
			/>

			<DatePicker
				size="small"
				format="DD.MM.YYYY"
				placeholder={t('Дата по')}
				value={dateBefore}
				onChange={(value) => onDateChange(value, EFilters.CREATED_AT_BEFORE)}
			/>

			<Select
				size="small"
				maxTagCount="responsive"
				onChange={(value) => onFilterChange(EFilters.TYPE, value)}
				value={getALLFilterValues(EFilters.TYPE)}
				options={Object.entries(transactionTypes).map(([value, label]) => ({ label, value }))}
				optionFilterProp="label"
				placeholder={t('Выбрать тип транзакции')}
				allowClear
			/>
		</div>
	);
};

export default TransactionsFilters;
