import { Typography } from 'antd';

import {
	ITransaction,
	TransactionAmount,
	TransactionButtons,
	TransactionReason,
	TransactionType,
} from 'entities/Transaction';
import { formatDate } from 'shared/utils';

const { Text } = Typography;

export const getTransaction = (transaction: ITransaction, key: number) => {
	const { amount, reason, created_at, comment } = transaction;

	return {
		key,
		created_at: <Text>{formatDate(new Date(created_at), 'full')}</Text>,
		type: <TransactionType amount={amount} />,
		amount: <TransactionAmount amount={amount} />,
		reason: <TransactionReason reason={reason} />,
		comment: (
			<Text ellipsis={{ tooltip: { title: comment } }} style={{ maxWidth: 200 }}>
				{comment || '-'}
			</Text>
		),
		buttons: <TransactionButtons transaction={transaction} />,
	};
};
