import { FC, HTMLAttributes, ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex, Table, TableColumnsType, Typography } from 'antd';

import { getTransaction, useGetTransactionsListQuery } from 'entities/Transaction';
import { TransactionsFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { useGetAppConfigQuery } from 'shared/api/commonApi';
import { useCommonSlice, useMedia } from 'shared/hooks';
import { EmptyState, OverlayLoader } from 'shared/ui';
import { getDefaultSortOrder, getTableSorter } from 'shared/utils';

interface DataType {
	key: React.Key;
	created_at: ReactNode;
	type: ReactNode;
	amount: ReactNode;
	reason: ReactNode;
	comment: ReactNode;
	buttons: ReactNode;
}

interface ITransactionListProps extends HTMLAttributes<HTMLDivElement> {}

export const TransactionList: FC<ITransactionListProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const isLg = useMedia('lg');
	const [searchParams, setSearchParams] = useSearchParams();
	const { currenciesMap } = useCommonSlice();
	const { data: appConfig } = useGetAppConfigQuery();
	const { data, isFetching } = useGetTransactionsListQuery(searchParams.toString());
	const hasData = !!data?.results?.length;

	const columns: TableColumnsType<DataType> = [
		{
			dataIndex: 'created_at',
			key: 'created_at',
			title: t('Дата'),
			defaultSortOrder: getDefaultSortOrder('created_at', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'type',
			key: 'type',
			title: t('Тип транзакции'),
			//defaultSortOrder: getDefaultSortOrder('type', searchParams),
			//sorter: true,
		},
		{
			dataIndex: 'amount',
			key: 'amount',
			title: `${t('Сумма')}, ${appConfig?.user?.balance.currency && currenciesMap[appConfig?.user?.balance.currency]}`,
			defaultSortOrder: getDefaultSortOrder('amount', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'reason',
			key: 'reason',
			title: t('Причина'),
			defaultSortOrder: getDefaultSortOrder('reason', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'comment',
			key: 'comment',
			title: t('Комментарий'),
		},
		{
			dataIndex: 'buttons',
			key: 'buttons',
			fixed: isLg ? 'right' : undefined,
			width: 50,
		},
	];

	const dataSource = hasData
		? data?.results?.map<DataType>((transaction, i) => {
				return getTransaction(transaction, i);
			})
		: [];

	return (
		<Flex {...props} vertical gap={16}>
			{isFetching && <OverlayLoader />}

			<Typography.Title level={5} style={{ margin: 0 }}>
				{t('История баланса')}
			</Typography.Title>

			<TransactionsFilters />

			{!hasData && !isFetching && <EmptyState title={t('Пока нет транзакций')} />}

			{hasData && (
				<>
					<Table<DataType>
						columns={columns}
						dataSource={dataSource}
						bordered={false}
						scroll={{ x: 'max-content' }}
						pagination={false}
						showSorterTooltip={false}
						onChange={getTableSorter<DataType>(searchParams, setSearchParams)}
					/>

					<Pagination count={data?.count || 1} />
				</>
			)}
		</Flex>
	);
};
