import { FC, HTMLAttributes } from 'react';

import { theme, Typography } from 'antd';

import { formatNumber } from 'shared/utils';

interface ITransactionAmountProps extends HTMLAttributes<HTMLDivElement> {
	amount: string;
}

export const TransactionAmount: FC<ITransactionAmountProps> = ({ amount, ...props }) => {
	const amountValue = !isNaN(Number(amount)) ? Number(amount) : 0;
	const {
		token: { colorSuccess, colorText },
	} = theme.useToken();

	return (
		<Typography.Text {...props} style={{ color: amountValue > 0 ? colorSuccess : colorText }}>
			{amountValue > 0 && '+'}
			{formatNumber(amountValue)}
		</Typography.Text>
	);
};
